contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address p) public payable {
        address before = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setOwner(p); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ? c.owner() == before : c.owner() == p);
    }
}

