pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address p) internal {
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setOwner(p) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ? c.owner() == before : c.owner() == p);
    }

    function testFuzz_run(address p) public {
